import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int tag resolves binary literals', () => {
    assert.equal(load('!!int 0b101'), 5);
    assert.equal(load('!!int -0b101'), -5);
  });
});

